const reply = {
  textarea: null,
  add_comment: null,
  mass_mention_node: null,
  unsubscribe: [],
  timer_id: null,
  responsible_select: null,

  init() {
    this.add_comment = document.querySelector(".btn.btn-default.issuelog");
    this.textarea = document.querySelector("#new_comment");
    this.mass_mention_node = document.querySelector("[value='Add corrective action']")
    this.responsible_select = document.querySelector(".default_btn.action_buttons.btn.btn-default"),

    this.clearResponsibleSelect()
    this.attachReply(this.getUserNodes());
    this.setListeners();
    this.attachMassMention()
  },

  clearResponsibleSelect() {
    this.responsible_select?.parentNode?.parentNode?.parentNode?.previousElementSibling?.querySelector("button").click()
  },

  setListeners() {
    this.add_comment.addEventListener("click", () => {
      // clear every subscriber which is button reply.
      this.unsubscribe.forEach((item) => item());
      //   after 3 seconds clear unsubscribe array
      // and attach new buttons after response from server received
      setTimeout(() => {
        this.unsubscribe = [];
        this.attachReply(this.getUserNodes());
      }, 3000);
    });
  },

  setTextAreaValue(value) {
    var setter = Object.getOwnPropertyDescriptor(
      HTMLTextAreaElement.prototype,
      "value"
    ).set;
    setter.call(this.textarea, this.textarea.value + " " + value);

    const event = new Event("input", { bubbles: true });
    this.textarea.dispatchEvent(event);
    this.focusTextAreaWithin(() => {
      this.textarea.focus();
    })(2000);
  },

  focusTextAreaWithin(fn) {
    return (timer) => {
      clearInterval(this.timer_id);
      this.timer_id = setTimeout(fn, timer);
    };
  },

  attachMassMention() {
    const nodes = [];
    for (const user of mass_mention) {
      const button = document.createElement("button");
      if (user.id === "4527") {
        button.style = "font-size: 11px; border-radius: 4px; margin-left: 4px; border: 1px solid black; background: #aadaec";
      } else {
        button.style = "font-size: 11px; border-radius: 4px; margin-left: 4px; border: 1px solid black; background: #fff";
      }
      button.textContent = user.value;
      button.type = "button";
      button.addEventListener("click", () => {
        this.setTextAreaValue(`@${user.value}(${user.id})`);
      });
      nodes.push(button);
    }
    this.textarea.parentNode.style.marginBottom = "8px;"
    this.mass_mention_node.parentNode.append(...nodes);
  },

  attachReply(nodes) {
    for (let idx of Array.from({ length: nodes.length }, (_, idx) => idx)) {
      const nodeObj = nodes[idx];

      const btn = document.createElement("button");
      btn.textContent = "Reply";
      btn.className = "btn btn-default";
      btn.addEventListener("click", () => {
        const user = this.getUser(users, nodeObj.name);
        if (!user) {
          new Notification(nodeObj.name + " not found.");
          return;
        }
        this.setTextAreaValue(`@${user.value}(${user.id})`);
      });
      this.unsubscribe.push(() => btn.remove());
      nodeObj.node.append(btn);
      nodeObj.node.style.display = "flex";
      nodeObj.node.style.gap = "6px";
      nodeObj.node.style.justifyContent = "center";
    }
  },

  getUser(users, surname) {
    if (surname in users) {
      return users[surname];
    } else {
      return null;
    }
  },

  getUserNodes() {
    const usersNodes = [];

    const table = document.querySelector(".issuelog_table");
    const tbody = table.querySelector("tbody");
    const nodes = tbody.querySelectorAll("tr");

    for (let node of [...nodes]) {
      const userRow = node.querySelector(".stableTd.commentUsername");
      if (!userRow) continue;
      const a = userRow.querySelector("a");
      if (!a) continue;
      const isMyNode =
        a.getAttribute("name") === document.querySelector("body").dataset.user;
      if (!isMyNode) {
        usersNodes.push({ node: userRow, name: a.getAttribute("name") });
      }
    }

    return usersNodes;
  },
};

const id = setInterval(() => {
  if (document.querySelector(".issuelog_table")) {
    clearInterval(id);
    setTimeout(() => {
      reply.init();
    }, 4000);
  }
}, 1000);
